#!/usr/bin/env python3
"""Create a full static isiZulu demonstration route set.

This is an AI-assisted draft for qualified translation and clinical review.
The HTML files are the deployable source; this script is optional authoring aid.
"""
from pathlib import Path
from html import escape

SITE=Path(__file__).resolve().parents[1]/'site'
Z=SITE/'zu'
P=Z/'paediatrics'
P.mkdir(parents=True,exist_ok=True)

def intro(crumb,title,lead,eyebrow='Isibonelo sokunakekelwa kwezingane'):
 return f'<div class="page-intro"><div class="container"><nav class="breadcrumb" aria-label="Indlela yekhasi"><a href="../index.html">Ekhaya</a> / <a href="index.html">Izingane</a> / {crumb}</nav><span class="eyebrow">{eyebrow}</span><h1>{title}</h1><p class="lead">{lead}</p></div></div>'
def page(path,title,description,main):
 relative=path.relative_to(SITE)
 css='../assets/css/main.css?v=20261025c' if path.parent==Z else '../../assets/css/main.css?v=20261025c'
 pr='../assets/css/print.css' if path.parent==Z else '../../assets/css/print.css'
 icon='../assets/images/favicon.svg' if path.parent==Z else '../../assets/images/favicon.svg'
 html=f'''<!doctype html><html lang="zu"><head><meta charset="utf-8" /><meta name="viewport" content="width=device-width, initial-scale=1" /><meta name="description" content="{escape(description,quote=True)}" /><meta name="robots" content="noindex, nofollow" /><title>{escape(title)} | HGRH Patient Access</title><link rel="icon" type="image/svg+xml" href="{icon}" /><link rel="stylesheet" href="{css}" /><link rel="stylesheet" href="{pr}" /></head><body><main id="main-content">{main}</main><footer class="site-footer"></footer></body></html>'''
 path.write_text(html)
 print(relative)

root='''<section class="hero"><div class="container hero-grid"><div><span class="eyebrow">Ulwazi olucacile ngezinyathelo</span><h1>Qala lapha.</h1><p class="lead">Lena indlela yesibonelo yokusiza abazali nabanakekeli bathole ulwazi ngomnyango wezingane eHarry Gwala Regional Hospital. Qinisekisa imininingwane yamanje esibhedlela.</p><div class="actions"><a class="button" href="paediatrics/index.html">Buka umnyango wezingane →</a><a class="button secondary" href="paediatrics/admissions.html">Buka ukwamukelwa</a></div></div><div class="hero-art"><img src="../assets/images/caregiver.svg" alt="Umdwebo womnakekeli nengane" width="520" height="480" /><span class="art-caption">Ulwazi oluhlelelwe imibuzo yabazali.</span></div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">Khetha okufunayo</span><h2>Sikusize ngani?</h2></div><p>Amakhasi abonisa indlela engase isebenze ngayo iwebhusayithi. Imininingwane yemitholampilo isalinde ukuqinisekiswa.</p></div><div class="grid grid-three"><article class="card"><span class="icon" aria-hidden="true">01</span><h3>Ukwamukelwa</h3><p>Bona isibonelo sezinyathelo zokungena esibhedlela.</p><a href="paediatrics/admissions.html">Vula ikhasi →</a></article><article class="card"><span class="icon peach" aria-hidden="true">02</span><h3>Imitholampilo</h3><p>Bona ithebula elivela kuwebhusayithi endala, elimakwe njengelingakaqinisekiswa.</p><a href="paediatrics/services.html">Buka izibonelo →</a></article><article class="card"><span class="icon" aria-hidden="true">03</span><h3>Izincwadi nosizo</h3><p>Vula ama-PDF e-WHO, amafomu asekelayo e-SASSA nemihlahlandlela yokuphrinta.</p><a href="paediatrics/education.html">Buka izinsiza →</a></article></div></div></section><section class="section-tight"><div class="container feature-band"><div><span class="eyebrow">Uxhumano olusemthethweni</span><h2>Qinisekisa ngaphambi kokuvakasha.</h2><p>Ikheli nenombolo enkulu yesibhedlela kuvela ekhasini le-KZN Health. Izindawo ezithile zomnyango wezingane azikaqinisekiswa.</p></div><a class="button light" href="paediatrics/contact.html">Ikheli nokuxhumana →</a></div></section>'''
page(Z/'index.html','Ekhaya','Isibonelo sesiZulu solwazi lokufinyelela ukunakekelwa kwezingane.',root)

paeds='''<section class="hero"><div class="container hero-grid"><div><span class="eyebrow">Umnyango wezingane · isibonelo</span><h1>Thola isinyathelo esilandelayo.</h1><p class="lead">Khetha umbuzo ofanele umndeni wakho. Lokhu akusona isiqondiso esigunyaziwe sesibhedlela; abasebenzi besibhedlela kufanele baqinisekise imininingwane.</p><div class="actions"><a class="button" href="admissions.html">Buka ukwamukelwa →</a><a class="button secondary" href="faqs.html">Imibuzo evamile</a></div></div><div class="hero-art"><img src="../../assets/images/caregiver.svg" alt="Umdwebo womnakekeli nengane" width="520" height="480" /><span class="art-caption">Qala ngombuzo wakho.</span></div></div></section><section class="section"><div class="container grid grid-three"><article class="card"><h2>Imitholampilo</h2><p>Imininingwane esuselwa esibonelweni sangaphambilini, ingakaqinisekiswa.</p><a href="services.html">Buka ithebula →</a></article><article class="card"><h2>Ukulungiselela</h2><p>Imibuzo nemibhalo ongabuza ngayo ngaphambi kokuvakasha.</p><a href="preparation.html">Lungiselela →</a></article><article class="card"><h2>Izinhlelo ezingase zibe khona</h2><p>Umqondo weqembu lokweseka omama bezinsana ezizalwe ngaphambi kwesikhathi.</p><a href="programmes.html">Buka umqondo →</a></article></div></section><section class="section-tight"><div class="container grid grid-two"><article class="card"><h2>Ulwazi lwe-WHO</h2><p>Ama-PDF angavulwa futhi aphrintwe; izincwadi zisatholakala ngesiNgisi.</p><a href="education.html">Buka imfundo →</a></article><article class="card"><h2>Amafomu nosizo</h2><p>Izixhumanisi zama-PDF asekelayo e-SASSA nohlu lokulungiselela.</p><a href="forms.html">Buka amafomu →</a></article></div></section>'''
page(P/'index.html','Izingane','Ikhasi lesibonelo sesiZulu lomnyango wezingane.',paeds)

adm=intro('Ukwamukelwa','Ukwamukelwa esibhedlela','Iwebhusayithi endala yayibonisa izinyathelo ezine. Lezi yizibonelo zangaphambilini, hhayi imiyalelo eqinisekisiwe.')+'''<section class="section"><div class="container content-layout"><div class="content-main"><section><h2>Izinyathelo ezazikulesi sibonelo</h2><ol class="journey-list"><li><strong>Ukudluliselwa</strong><span>Isibonelo sangaphambilini: incwadi kadokotela noma ukufika ngosizo oluphuthumayo.</span></li><li><strong>Ukuhlolwa</strong><span>Isibonelo: abasebenzi bahlola isidingo sokungeniswa.</span></li><li><strong>Ukubhaliswa</strong><span>Isibonelo: kuhlolwa imibhalo edingekayo.</span></li><li><strong>Ukungeniswa</strong><span>Isibonelo: ingane iqondiswa ewadini elifanele.</span></li></ol></section><section><h2>Imibhalo eyayiphakanyisiwe</h2><p>Isitifiketi sokuzalwa noma i-ID yengane; i-ID yomzali noma umnakekeli; incwadi yokudluliselwa uma ikhona; i-Road to Health card; amarekhodi adlule. <strong>Buza abasebenzi ukuthi yini edingekayo kuwe.</strong></p></section><section><h2>Izikhathi ezazikulesi sibonelo</h2><div class="note"><strong>Akukaqinisekiswa:</strong> ikhasi elidala lalithi ukungeniswa okuhleliwe ngoMsombuluko kuya kuLwesihlanu, 08:00–16:00; usizo oluphuthumayo nge-Emergency Department. Leli khasi aliqinisekisi lezi zikhathi.</div><p>Uma udinga usizo oluphuthumayo, funa usizo oluphuthumayo endaweni yakini. Bheka <a href="contact.html">ikhasi lokuxhumana</a> ngenombolo enkulu yesibhedlela.</p></section><div class="actions"><a class="button" href="faqs.html">Imibuzo evamile →</a></div></div><aside class="side-panel"><h2>Isimo solwazi</h2><p>Lezi zibonelo zivela <a href="https://github.com/NightWing617/website_templates/blob/main/admissions.html">kuwebhusayithi endala</a>. Isibhedlela asikaqinisekisi indlela yamanje yokwamukelwa.</p></aside></div></section>'''
page(P/'admissions.html','Ukwamukelwa','Izinyathelo zokwamukelwa ezivela kusibonelo sangaphambilini.',adm)

svc=intro('Imitholampilo','Izibonelo zemitholampilo','Ithebula elingezansi livela kuwebhusayithi endala. Akusilo uhlelo lwamanje oluqinisekisiwe. Ungalisebenzisi ukuhlela ukuvakasha.')+'''<section class="section"><div class="container"><div class="source-alert"><div><h2>Umthombo osemthethweni</h2><p>I-KZN Health ibala ukunakekelwa kwezingane njengenye yezinsiza zesibhedlela. Ayinikezi lolu hlelo lwemitholampilo.</p></div><a class="button secondary" href="https://www.kznhealth.gov.za/provincial-hospitals/harry-gwala-hospital/harry-gwala-services/">Vula uhlu olusemthethweni ↗</a></div><h2>Ithebula lesibonelo sangaphambilini</h2><div class="table-wrap"><table class="clinic-table"><caption>Zonke izikhathi nemithetho kuleli thebula azikaqinisekiswa</caption><thead><tr><th scope="col">Usuku</th><th scope="col">Isikhathi</th><th scope="col">Igama lomtholampilo</th><th scope="col">Okushiwo yisibonelo</th></tr></thead><tbody><tr><th scope="row">uMsombuluko</th><td>08:00–16:00</td><td lang="en">General Paediatrics</td><td>Incwadi yokudluliselwa</td></tr><tr><th scope="row">uLwesibili</th><td>09:00–12:00</td><td lang="en">Growth &amp; Development</td><td><span lang="en">Road to Health card</span></td></tr><tr><th scope="row">uLwesithathu</th><td>08:00–16:00</td><td lang="en">Specialist Clinics</td><td>Ukudluliselwa kochwepheshe</td></tr><tr><th scope="row">uLwesine</th><td>10:00–14:00</td><td lang="en">Asthma Education</td><td>Ukuxilongwa kwangaphambili</td></tr><tr><th scope="row">uLwesihlanu</th><td>08:00–16:00</td><td lang="en">Immunisation</td><td><span lang="en">Road to Health card</span></td></tr></tbody></table></div><div class="note"><strong>Qinisekisa kuqala:</strong> shayela inombolo enkulu yesibhedlela <a href="tel:+27333954911">+27 (0) 33 395 4911</a> ubuze umtholampilo, isikhathi nendawo efanele. Indawo ye-“Level 2 Paediatrics wing” yayikusibonelo esidala kodwa ayikaqinisekiswa.</div></div></section>'''
page(P/'services.html','Imitholampilo','Ithebula lemitholampilo langaphambili elingakaqinisekiswa.',svc)

prep=intro('Ukuvakashela','Lungiselela ukuvakasha','Leli khasi linikeza imibuzo ongayibuza, hhayi uhlu lwemithetho yesibhedlela.')+'''<section class="section"><div class="container content-layout"><div class="content-main"><section><h2>Ngaphambi kokuhamba</h2><ol class="steps"><li>Qinisekisa indawo, usuku nesikhathi usebenzisa imiyalelo yakho yokuqokwa noma yabadokotela.</li><li>Buza abasebenzi ukuthi yimiphi imibhalo namarekhodi okumele uwaphathe.</li><li>Bhala imibuzo yakho ukuze uyibuze ngesikhathi sokuvakasha.</li><li>Buza ukuthi ubani okufanele umbone uma ufika.</li></ol></section><section><h2>Izinsiza ongaziphrinta</h2><p><a href="../../documents/preterm-caregiver-questions.pdf" lang="en">Download the premature baby questions PDF (English) ↓</a></p><p><a href="../../documents/care-dependency-preparation-checklist.pdf" lang="en">Download the Care Dependency preparation checklist (English) ↓</a></p><p>Izinguqulo zesiZulu zalezi zincwadi zisalinde ukubuyekezwa.</p></section></div><aside class="side-panel"><h2>Qinisekisa</h2><p>Uhlu lwemibhalo nezindawo ezithile ludinga isiqinisekiso sesibhedlela. <a href="contact.html">Bheka ukuxhumana →</a></p></aside></div></section>'''
page(P/'preparation.html','Ukuvakashela','Imibuzo yokulungiselela ukuvakasha.',prep)

edu=intro('Imfundo','Izinsiza zemfundo','Vula ama-PDF avela ngqo ku-WHO. Amadokhumenti angesiNgisi; cela abasebenzi bezempilo bakusize ukhethe okufanele.')+'''<section class="section"><div class="container"><div class="note"><strong>Qaphela:</strong> i-WHO ayigunyazanga le webhusayithi. Izincwadi zodokotela azisona iseluleko esiqondene nengane yakho.</div><div class="section-head"><div><span class="eyebrow">Omama nabanakekeli</span><h2>Ama-PDF angadawunilodwa</h2></div></div><div class="grid grid-two"><article class="card resource-card"><span class="kicker">WHO · 2022</span><h3 lang="en">Caregiver skills training</h3><p>Umhlahlandlela wezithombe wemindeni yezingane ezineminyaka engu-2–9 ezinokubambezeleka kokukhula noma ukukhubazeka.</p><a class="button small" href="https://iris.who.int/server/api/core/bitstreams/60c77ee8-1ed4-410d-a647-bb4d2e1f9e95/content" lang="en">Download WHO PDF ↗</a></article><article class="card resource-card"><span class="kicker">WHO / UNICEF · 2021</span><h3 lang="en">Infant-feeding counselling cards</h3><p>Amakhadi enzelwe abasebenzi bezempilo ukuthi baxoxe ngawo nabazali nabanakekeli.</p><a class="button small" href="https://iris.who.int/server/api/core/bitstreams/082ccd9f-dd2a-45dd-a0ff-7c4b7f07bca1/content" lang="en">Download WHO PDF ↗</a></article></div><div class="section-head section-tight"><div><span class="eyebrow">Abasebenzi bezempilo</span><h2>Izincwadi zobungcweti</h2></div><p>Lezi zidinga ukuhunyushwa yochwepheshe nemithetho yendawo.</p></div><div class="grid grid-two"><article class="card"><h3 lang="en">Essential newborn care course</h3><a href="https://www.who.int/publications/i/item/9789240112698" lang="en">WHO book and download ↗</a></article><article class="card"><h3 lang="en">Care of the preterm or low-birth-weight infant</h3><a href="https://www.who.int/publications/i/item/9789240058262/" lang="en">WHO guideline and download ↗</a></article></div></div></section>'''
page(P/'education.html','Imfundo','Izixhumanisi zama-PDF e-WHO nabafundi abahlukene.',edu)

faq=intro('Imibuzo','Imibuzo evamile','Izimpendulo zikhombisa isimo salesi sibonelo. Qinisekisa imininingwane yamanje nesibhedlela.')+'''<section class="section"><div class="container content-layout"><div class="content-main"><div class="faq-list"><details><summary>Ngiyaphi uma ngifika?</summary><p>Ikheli lesibhedlela liku <a href="contact.html">ikhasi lokuxhumana</a>. Indawo ethile yomnyango wezingane ayikaqinisekiswa; buza abasebenzi noma sebenzisa imiyalelo yesikhathi sakho.</p></details><details><summary>Ingabe uhlelo lwemitholampilo lusekhona?</summary><p><a href="services.html">Ithebula lemitholampilo</a> livela kuwebhusayithi endala futhi alimakiwe njengohlelo lwamanje. Qinisekisa nosibhedlela.</p></details><details><summary>Ngingabhalisela iqembu lokweseka omama bezinsana ezizalwe ngaphambi kwesikhathi?</summary><p>Cha. <a href="programmes.html">Lelo qembu</a> lisewumqondo, alikavulwa futhi ayikho indlela yokubhalisa kule webhusayithi.</p></details><details><summary>Ngingalitholaphi ifomu lesibonelelo?</summary><p>Ikhasi <a href="forms.html">lamafomu nosizo</a> lixhumanisa amafomu asekelayo e-SASSA. Ifomu lesicelo uqobo litholakala ehhovisi le-SASSA ngokusho kukahulumeni.</p></details><details><summary>Ingabe lolu hlelo lusemthethweni?</summary><p>Cha. Lena iwebhusayithi yesibonelo engakagunyazwa yisibhedlela.</p></details></div></div><aside class="side-panel"><h2>Udinga ulwazi lwamanje?</h2><p>Bheka <a href="https://www.kznhealth.gov.za/provincial-hospitals/harry-gwala-hospital/">ikhasi elisemthethweni lesibhedlela</a> noma ubuze abasebenzi.</p></aside></div></section>'''
page(P/'faqs.html','Imibuzo','Imibuzo nezimpendulo ngesibonelo sewebhusayithi.',faq)

contact=intro('Xhumana','Ikheli nokuxhumana','Ikheli nezinombolo ezingezansi zishicilelwe yi-KZN Health zesibhedlela sonke. Indawo ethile yomnyango wezingane isadinga ukuqinisekiswa.')+'''<section class="section"><div class="container"><div class="grid grid-two"><article class="card"><span class="kicker">Ikheli elisemthethweni</span><h2>Harry Gwala Regional Hospital</h2><address>Lot 89, Selby Msimang Road<br/>Plessislaer, Pietermaritzburg<br/>KwaZulu-Natal, South Africa</address><a href="https://www.google.com/maps/search/?api=1&amp;query=Harry+Gwala+Regional+Hospital%2C+Lot+89+Selby+Msimang+Road%2C+Plessislaer%2C+Pietermaritzburg">Sesha ikheli e-Google Maps ↗</a></article><article class="card"><span class="kicker">Izinombolo zesibhedlela sonke</span><h2>Shayela ukuze uqinisekise</h2><p>Inombolo enkulu: <a class="number-link" href="tel:+27333954911">+27 (0) 33 395 4911</a></p><p>Isikhulu sobudlelwano nomphakathi: <a class="number-link" href="tel:+27333954020">033 395 4020</a></p><p>Lezi azibhalwanga njengezinombolo zokubhuka noma zezimo eziphuthumayo zomnyango wezingane.</p></article></div><div class="section-tight"><h2>Ingabe umnyango wezingane ukuphi?</h2><p>Iwebhusayithi endala yayithi “Main Building, Level 2 – Paediatrics Wing”. Le ndawo ayikaqinisekiswa, ngakho ayisona isiqondiso sokuhamba. Shayela inombolo enkulu ubuze indawo efanele isikhathi sakho.</p><p>Ikhasi elisemthethweni linikeza izikhathi zokuvakasha zesibhedlela sonke. Qinisekisa imithetho yewadi lezingane ngaphambi kokuvakasha.</p><a href="https://www.kznhealth.gov.za/provincial-hospitals/harry-gwala-hospital/">Vula umthombo osemthethweni ↗</a></div></div></section>'''
page(P/'contact.html','Ukuxhumana','Ikheli nezinombolo ezisemthethweni zesibhedlela sonke.',contact)

programmes=intro('Izinhlelo','Imibono yokweseka imindeni','Lezi yiziphakamiso kuphela. Alikho iqembu eliqinisekisiwe noma indlela yokubhalisa kule webhusayithi.')+'''<section class="section"><div class="container grid grid-two"><article class="feature-card"><span class="status-pill">Umbono kuphela · akukho ukubhalisa</span><h2>Iqembu lomama bezinsana ezizalwe ngaphambi kwesikhathi</h2><p>Umbono wokuthi abazali bathole indawo yokuxoxa nokwesekana uma isibhedlela sifuna ukuhlola lolu hlelo. Isikhathi, abasebenzi nendlela yokungena akukanqunywa.</p><a href="../../documents/preterm-caregiver-questions.pdf" lang="en">Download printable questions (English) ↓</a></article><article class="feature-card"><span class="status-pill">Umbono kuphela</span><h2>Izifundo zabanakekeli</h2><p>Izifundo ezimfushane ezingase zenziwe ngemithombo ye-WHO ngemva kokubuyekezwa yisibhedlela.</p><a href="education.html">Buka izinsiza →</a></article><article class="feature-card"><span class="status-pill">Usizo olusemthethweni lukhona kwenye indawo</span><h2>Usizo lwezibonelelo</h2><p>Bheka ulwazi lukahulumeni namafomu asekelayo e-SASSA. Leli khasi alithumeli isicelo.</p><a href="forms.html">Amafomu nosizo →</a></article><article class="feature-card"><span class="status-pill">Akukho mininingwane eqoqwayo</span><h2>Buza abasebenzi besibhedlela</h2><p>Uma ufuna ukwazi ukuthi yiluphi usizo lwabazali olukhona manje, buza esibhedlela. Ungathumeli ulwazi lomndeni kule webhusayithi.</p></article></div></section>'''
page(P/'programmes.html','Izinhlelo','Imibono yezinhlelo ezingakavulwa.',programmes)

forms=intro('Amafomu nosizo','Amafomu nosizo','Vula ama-PDF asekelayo avela ku-SASSA. Ifomu lesicelo uqobo litholakala ehhovisi le-SASSA; alitholakali kule webhusayithi.')+'''<section class="section"><div class="container"><div class="source-alert"><div><h2>Isicelo sangempela senziwa nge-SASSA.</h2><p>Uhulumeni waseNingizimu Afrika uthi amafomu ezicelo ze-Care Dependency Grant ne-Disability Grant awatholakali ku-inthanethi. Buza ihhovisi le-SASSA ngenqubo yamanje.</p></div><a class="button secondary" href="https://www.gov.za/services/services-residents/parenting/child-care/care-dependency-grant">Ulwazi lukahulumeni ↗</a></div><div class="grid grid-three section-tight"><article class="card"><span class="kicker">Ifomu elisekelayo lengane</span><h3 lang="en">Care Dependency Grant affidavit</h3><p>I-PDF esemthethweni ye-SASSA. Akusilo ifomu lesicelo.</p><a href="https://services.sassa.gov.za/portal/r/sassa/files/static/v61/Affivadit_CDG.pdf" lang="en">Open / print SASSA PDF ↗</a></article><article class="card"><span class="kicker">Ifomu elisekelayo labadala</span><h3 lang="en">Disability Grant affidavit</h3><p>Isibonelelo sabadala. Buza i-SASSA ukuthi yini efanele ingane yakho.</p><a href="https://services.sassa.gov.za/portal/r/sassa/files/static/v60/Affivadit_DG.pdf" lang="en">Open / print SASSA PDF ↗</a></article><article class="card"><span class="kicker">Ukuhlolwa</span><h3 lang="en">Medical assessment referral form</h3><p>Buza i-SASSA noma uchwepheshe ukuthi leli fomu lidingeka yini.</p><a href="https://services.sassa.gov.za/portal/r/sassa/files/static/v61/MedicalAssessmentReferralForm.pdf" lang="en">Open / print SASSA PDF ↗</a></article></div><div class="feature-band"><div><h2>Uhlu lwemibuzo lokuphrinta</h2><p>Lo mbhalo awusona isicelo se-SASSA. Uyakusiza ulungiselele imibuzo; useNgisini okwamanje.</p></div><a class="button light" href="../../documents/care-dependency-preparation-checklist.pdf" lang="en">Download checklist PDF (English) ↓</a></div></div></section>'''
page(P/'forms.html','Amafomu nosizo','Amafomu asekelayo e-SASSA nezixhumanisi ezisemthethweni.',forms)
